1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.section.clazz.Flow;
4	import net.officefloor.plugin.variable.Out;
5	import net.officefloor.server.http.HttpHeader;
6	import net.officefloor.server.http.ServerHttpConnection;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.repository.OwnerRepository;
9	
10	/**
11	 * First step of {@code POST /api/owners}: honours the optional {@code Idempotency-Key}
12	 * header. When a key has already been seen (see {@link IdempotencyStore}) the originally
13	 * created owner is re-loaded and the {@code existing} branch responds with it (200),
14	 * short-circuiting validation, the duplicate checks and a second insert. Otherwise the
15	 * {@code proceed} branch runs the normal create pipeline.
16	 *
17	 * <p>Reads only the header, never the request body, so the downstream {@code validate}
18	 * step remains the single {@code @RequestBody} binder. The key is republished as a
19	 * variable so {@link RecordIdempotency} can associate it with the created owner after save.
20	 */
21	public class CheckIdempotencyKey {
22	
23	    private static final String IDEMPOTENCY_KEY = "Idempotency-Key";
24	
25	    public void service(ServerHttpConnection connection, IdempotencyStore store,
26	            OwnerRepository ownerRepository, Out<String> idempotencyKey, Out<Owner> replayOwner,
27	            @Flow("existing") Continuation existing, @Flow("proceed") Continuation proceed) {
28	
29	        HttpHeader header = connection.getRequest().getHeaders().getHeader(IDEMPOTENCY_KEY);
30	        String key = header == null ? null : header.getValue();
31	        idempotencyKey.set(key);
32	
33	        if (key != null && !key.isBlank()) {
34	            Integer priorOwnerId = store.find(key);
35	            if (priorOwnerId != null) {
36	                Owner priorOwner = tryLoad(ownerRepository, priorOwnerId);
37	                if (priorOwner != null) {
38	                    replayOwner.set(priorOwner);
39	                    existing.run(); // replay the original create: 200 with the original owner
40	                    return;
41	                }
42	            }
43	        }
44	
45	        proceed.run(); // first time this key (or no key): run the normal create pipeline
46	    }
47	
48	    /** Re-load the previously created owner, treating a since-removed record as unseen. */
49	    private static Owner tryLoad(OwnerRepository ownerRepository, Integer ownerId) {
50	        try {
51	            return ownerRepository.findById(ownerId);
52	        }
53	        catch (RuntimeException ex) {
54	            return null; // e.g. ObjectRetrievalFailureException — fall through to a fresh create
55	        }
56	    }
57	}
