1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	import net.officefloor.plugin.variable.Val;
8	import org.springframework.samples.petclinic.model.Owner;
9	
10	/**
11	 * Assigns the owner's {@code householdId} deterministically: the first 12 hexadecimal
12	 * characters of the SHA-256 digest over {@code normalizedLastName + '|' + postcode}. Two
13	 * owners with the same last name and postcode therefore always derive the <em>same</em>
14	 * {@code householdId} — they are automatically the same household, with no opt-in and no
15	 * back-fill. Runs after {@link BuildOwner} (so the entity carries its stored last name and
16	 * postcode) and before {@link CheckOwnerIdentityUnique} (so the household id is available
17	 * to the duplicate block) and {@link AssignHouseholdSize}.
18	 *
19	 * <p>The request flag {@code sharesHousehold} no longer creates the link; it only lets a
20	 * second owner in an existing household bypass the duplicate block (see
21	 * {@link CheckOwnerIdentityUnique}).
22	 */
23	public class AssignHousehold {
24	
25	    public void service(@Val Owner owner) {
26	        String key = normalize(owner.getLastName()) + "|" + nullToEmpty(owner.getPostcode());
27	        owner.setHouseholdId(hash12(key));
28	    }
29	
30	    /** The first 12 lower-case hex characters of SHA-256 over the UTF-8 bytes of {@code value}. */
31	    private static String hash12(String value) {
32	        try {
33	            byte[] digest = MessageDigest.getInstance("SHA-256")
34	                    .digest(value.getBytes(StandardCharsets.UTF_8));
35	            StringBuilder sb = new StringBuilder(12);
36	            for (int i = 0; i < 6; i++) {
37	                sb.append(String.format("%02x", digest[i]));
38	            }
39	            return sb.toString();
40	        }
41	        catch (NoSuchAlgorithmException e) {
42	            throw new IllegalStateException("SHA-256 not available", e);
43	        }
44	    }
45	
46	    private static String nullToEmpty(String value) {
47	        return value == null ? "" : value;
48	    }
49	
50	    /** Lower-cased, trimmed, with internal whitespace runs collapsed to a single space. */
51	    private static String normalize(String value) {
52	        if (value == null) {
53	            return "";
54	        }
55	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
56	    }
57	}
