1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.OwnerIdentityConflictException;
8	
9	/**
10	 * The duplicate-detection block. Because the {@code householdId} is now derived
11	 * deterministically from {@code (lastName, postcode)} (see {@link AssignHousehold}), two
12	 * owners that share a last name and postcode are the same household. A second owner in an
13	 * existing household is therefore rejected as a household duplicate (409) — <em>unless</em>
14	 * the request opts in via {@code sharesHousehold}, which declares the new owner a member of
15	 * that household and bypasses the block.
16	 *
17	 * <p>Runs after {@link BuildOwner} and {@link AssignHousehold} (so the new owner carries its
18	 * computed {@code householdId}) and before {@link SaveOwner} (so a duplicate is a 409 rather
19	 * than a persisted record).
20	 */
21	public class CheckOwnerIdentityUnique {
22	
23	    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository)
24	            throws OwnerIdentityConflictException {
25	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
26	            return; // declared household member: bypass the duplicate block
27	        }
28	        String householdId = owner.getHouseholdId();
29	        for (Owner existing : ownerRepository.findAll()) {
30	            if (existing.isDeleted()) {
31	                continue; // a soft-deleted owner no longer blocks a duplicate
32	            }
33	            if (householdId.equals(existing.getHouseholdId())) {
34	                throw new OwnerIdentityConflictException(householdId);
35	            }
36	        }
37	    }
38	}
