3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Assigns the owner's {@code householdSize}: the number of owners that share the new
9	 * owner's {@code householdId} once this create is included. Runs after
10	 * {@link AssignHousehold} (so the shared {@code householdId} is set and back-filled onto
11	 * the existing housemates) and before {@link SaveOwner}, so the value counts the existing
12	 * housemates plus the one being created. An owner not linked into a household (null
13	 * {@code householdId}) is a household of one. The value is fixed at creation time and
14	 * persisted with the owner.
15	 */
16	public class AssignHouseholdSize {
17	
18	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
19	        String householdId = owner.getHouseholdId();
20	        int size = 1; // the owner being created (not yet persisted)
21	        if (householdId != null) {
22	            for (Owner existing : ownerRepository.findAll()) {
23	                if (householdId.equals(existing.getHouseholdId())) {
24	                    size++;
25	                }
26	            }
27	        }
28	        owner.setHouseholdSize(size);
29	    }
30	}
