1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.HashSet;
7	import java.util.Set;
8	
9	import net.officefloor.plugin.variable.Val;
10	import org.springframework.samples.petclinic.model.Locality;
11	import org.springframework.samples.petclinic.model.Owner;
12	import org.springframework.samples.petclinic.repository.OwnerRepository;
13	
14	/**
15	 * Assigns the owner's {@code customerCode}, formatted {@code <REGION>-<HASH8>}: REGION is
16	 * the region code derived from the owner's postcode (see {@link Locality#regionOf}) and
17	 * HASH8 is the first 8 upper-case hexadecimal characters of the SHA-256 digest over the
18	 * concatenation of the owner's normalized (E.164) telephone and lastName (e.g.
19	 * {@code NSW-1A2B3C4D}). When the computed code collides with an existing owner's
20	 * {@code customerCode}, {@code -<n>} is appended with the smallest {@code n} of 2 or more
21	 * that makes it unique. Runs after {@link BuildOwner} (so the telephone is already
22	 * normalized) and before {@link SaveOwner}.
23	 */
24	public class AssignCustomerCode {
25	
26	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
27	        String region = Locality.regionOf(owner.getPostcode());
28	        String hash8 = hash8(nullToEmpty(owner.getTelephone()) + nullToEmpty(owner.getLastName()));
29	        String base = region + "-" + hash8;
30	        owner.setCustomerCode(deduplicate(base, existingCodes(ownerRepository)));
31	    }
32	
33	    private static Set<String> existingCodes(OwnerRepository ownerRepository) {
34	        Set<String> codes = new HashSet<>();
35	        for (Owner existing : ownerRepository.findAll()) {
36	            String code = existing.getCustomerCode();
37	            if (code != null) {
38	                codes.add(code);
39	            }
40	        }
41	        return codes;
42	    }
43	
44	    /** Returns {@code base}, or {@code base-<n>} with the smallest {@code n >= 2} not in {@code taken}. */
45	    private static String deduplicate(String base, Set<String> taken) {
46	        if (!taken.contains(base)) {
47	            return base;
48	        }
49	        for (int n = 2; ; n++) {
50	            String candidate = base + "-" + n;
51	            if (!taken.contains(candidate)) {
52	                return candidate;
53	            }
54	        }
55	    }
56	
57	    private static String nullToEmpty(String value) {
58	        return value == null ? "" : value;
59	    }
60	
61	    /** The first 8 upper-case hex characters of SHA-256 over the UTF-8 bytes of {@code value}. */
62	    private static String hash8(String value) {
63	        try {
64	            byte[] digest = MessageDigest.getInstance("SHA-256")
65	                    .digest(value.getBytes(StandardCharsets.UTF_8));
66	            StringBuilder sb = new StringBuilder(8);
67	            for (int i = 0; i < 4; i++) {
68	                sb.append(String.format("%02X", digest[i]));
69	            }
70	            return sb.toString();
71	        }
72	        catch (NoSuchAlgorithmException e) {
73	            throw new IllegalStateException("SHA-256 not available", e);
74	        }
75	    }
76	}
